#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const PATCH_NAME = 'SMaRT-PDM System Maintenance + Backup + Responsive Maintenance v2';
const MARKER = 'SMART-PDM_SYSTEM_MAINTENANCE_BACKUP_RESPONSIVE_V1';
const dryRun = process.argv.includes('--dry-run');
const explicitRoot = process.argv.find((arg) => arg !== '--dry-run' && !arg.endsWith('.js') && arg !== process.argv[0] && arg !== process.argv[1]);

const PAYLOADS = {"admin/frontend/src/pages/maintenance/SystemPanel.jsx":"","admin/backend/services/systemMaintenanceService.js":"","admin/backend/controllers/systemMaintenanceController.js":"","admin/backend/routes/systemMaintenanceRoutes.js":"","admin/backend/services/systemMaintenanceMigrationService.js":"","supabase/migrations/20260825000100_system_maintenance_controls.sql":"","mobile/frontend/lib/core/maintenance/maintenance_mode_gate.dart":""};

const REQUIRED_EXISTING = [
  'admin/frontend/src/pages/maintenance/GeneralPanel.jsx',
  'admin/frontend/src/pages/maintenance/Maintenance.jsx',
  'admin/backend/server/server.js',
  'mobile/frontend/lib/app/app.dart',
];

function fail(message) {
  const error = new Error(message);
  error.isPatchError = true;
  throw error;
}

function normalize(text) {
  return String(text).replace(/\r\n/g, '\n');
}

function detectEol(text) {
  return String(text).includes('\r\n') ? '\r\n' : '\n';
}

function restoreEol(text, eol) {
  return eol === '\r\n' ? text.replace(/\n/g, '\r\n') : text;
}

function decodePayload(relativePath) {
  const encoded = PAYLOADS[relativePath];
  if (!encoded) fail(`Missing embedded payload: ${relativePath}`);
  return Buffer.from(encoded, 'base64').toString('utf8');
}

function findRepoRoot(input) {
  const candidates = [];
  if (input) candidates.push(path.resolve(input));
  candidates.push(process.cwd());
  candidates.push(__dirname);

  for (const candidate of candidates) {
    let current = candidate;
    for (let depth = 0; depth < 8; depth += 1) {
      if (REQUIRED_EXISTING.every((relative) => fs.existsSync(path.join(current, relative)))) {
        return current;
      }
      const parent = path.dirname(current);
      if (parent === current) break;
      current = parent;
    }
  }

  fail('Could not find the SMaRT-PDM repository root.');
}

function replaceOnce(source, before, after, label) {
  const index = source.indexOf(before);
  if (index < 0) fail(`${label}: expected source block was not found.`);
  if (source.indexOf(before, index + before.length) >= 0) {
    fail(`${label}: expected source block matched more than once.`);
  }
  return source.slice(0, index) + after + source.slice(index + before.length);
}

function replaceRegexOnce(source, pattern, replacement, label) {
  const matches = [...source.matchAll(pattern)];
  if (matches.length !== 1) {
    fail(`${label}: expected exactly 1 matching source block, found ${matches.length}.`);
  }
  return source.replace(pattern, replacement);
}

function upsertGeneratedFile(staged, repoRoot, relativePath, content) {
  const absolute = path.join(repoRoot, relativePath);
  const exists = fs.existsSync(absolute);
  const original = exists ? fs.readFileSync(absolute, 'utf8') : null;

  if (exists && normalize(original) === normalize(content)) {
    staged.set(relativePath, { original, next: original, existed: true, changed: false });
    return;
  }

  if (exists && !normalize(original).includes(MARKER) && relativePath.endsWith('SystemPanel.jsx')) {
    // SystemPanel is an intentional full replacement of the currently hardcoded placeholder panel.
  } else if (exists && relativePath !== 'admin/frontend/src/pages/maintenance/SystemPanel.jsx') {
    fail(`${relativePath} already exists with different content. Refusing to overwrite it.`);
  }

  const next = relativePath.endsWith('.jsx') || relativePath.endsWith('.js') || relativePath.endsWith('.dart')
    ? `${content.trimEnd()}\n`
    : content;
  staged.set(relativePath, { original, next, existed: exists, changed: true });
}

function patchGeneralPanel(source) {
  let next = normalize(source);
  if (next.includes('SMART-PDM_SYSTEM_PANEL_LIVE_V1')) return next;

  const wrappedPattern = /<EditableRegion\s+editing=\{generalEditing\}>\s*<SystemPanel\s+embedded\s*\/>\s*<\/EditableRegion>/m;
  if (wrappedPattern.test(next)) {
    next = next.replace(
      wrappedPattern,
      `{/* SMART-PDM_SYSTEM_PANEL_LIVE_V1 */}\n                        <SystemPanel embedded editing={generalEditing} />`
    );
  } else if (/<SystemPanel\s+embedded\s*\/>/.test(next)) {
    next = replaceRegexOnce(
      next,
      /<SystemPanel\s+embedded\s*\/>/g,
      `{/* SMART-PDM_SYSTEM_PANEL_LIVE_V1 */}\n                        <SystemPanel embedded editing={generalEditing} />`,
      'General > System live panel'
    );
  } else if (!next.includes('<SystemPanel embedded editing={generalEditing} />')) {
    fail('General > System live panel: expected current SystemPanel usage was not found.');
  }

  return next;
}

function patchMaintenance(source) {
  let next = normalize(source);
  if (next.includes('SMART-PDM_MAINTENANCE_VIEWPORT_FIT_V1')) return next;

  next = replaceRegexOnce(
    next,
    /<div className="sticky top-0 z-20[^\"]*px-2 py-2">/g,
    `<div className="sticky top-0 z-20 shrink-0 bg-transparent px-2 py-2">`,
    'Maintenance top navigation wrapper'
  );

  next = next.replace(
    `className={\`flex h-9 shrink-0 items-center gap-1.5 whitespace-nowrap rounded-lg px-3 font-sans text-sm font-semibold leading-none tracking-[-0.01em] transition-colors \${`,
    `className={\`flex min-h-9 shrink-0 items-center gap-1.5 whitespace-nowrap rounded-lg px-3 py-2 font-sans text-sm font-semibold leading-tight tracking-[-0.01em] transition-colors \${`
  );

  const rootPattern = /<div\s+className="flex flex-col"\s+style=\{\{\s*background: theme\.mainBg,\s*minHeight: 'calc\(100dvh - 120px\)',\s*\}\}\s*>/m;
  if (rootPattern.test(next)) {
    next = next.replace(
      rootPattern,
      `<div\n      className="flex h-full min-h-0 w-full min-w-0 max-w-full flex-col overflow-hidden"\n      style={{ background: theme.mainBg }}\n      data-maintenance-viewport-fit="true"\n    >`
    );
  } else if (!next.includes('data-maintenance-viewport-fit="true"')) {
    fail('Maintenance viewport root: current root layout did not match.');
  }

  next = next.replace(
    `<div className="flex-1 p-2.5">`,
    `<div className="min-h-0 min-w-0 flex-1 p-2.5">`
  );

  next = next.replace(
    `<Card className="flex h-full flex-col overflow-hidden rounded-xl border-stone-200 shadow-none">`,
    `<Card className="flex h-full min-h-0 min-w-0 flex-col overflow-hidden rounded-xl border-stone-200 shadow-none">`
  );

  const scrollingBlock = /className=\{`flex-1 overflow-auto \$\{\s*isRegistry\s*\? 'max-h-\[calc\(100vh-132px\)\] p-2\.5'\s*: 'max-h-\[calc\(100vh-132px\)\] p-3'\s*\}`\}/m;
  if (scrollingBlock.test(next)) {
    next = next.replace(
      scrollingBlock,
      `className={\`min-h-0 min-w-0 flex-1 overflow-auto \${isRegistry ? 'p-2.5' : 'p-3'}\`}`
    );
  } else if (!next.includes(`min-h-0 min-w-0 flex-1 overflow-auto`)) {
    fail('Maintenance scroll container: current max-height contract did not match.');
  }

  next = next.replace(
    `export default function Maintenance() {`,
    `// SMART-PDM_MAINTENANCE_VIEWPORT_FIT_V1\nexport default function Maintenance() {`
  );

  return next;
}

function patchServer(source) {
  let next = normalize(source);
  if (next.includes('SMART-PDM_SYSTEM_MAINTENANCE_SERVER_V1')) return next;

  next = replaceOnce(
    next,
    `const { ensureCanonicalIotOcrMigration } = require('../services/liveMigrationService');`,
    `const { ensureCanonicalIotOcrMigration } = require('../services/liveMigrationService');\nconst { ensureSystemMaintenanceMigration } = require('../services/systemMaintenanceMigrationService'); // SMART-PDM_SYSTEM_MAINTENANCE_SERVER_V1`,
    'Server migration import'
  );

  next = replaceOnce(
    next,
    `const generalSettingRoutes = require('../routes/generalSettingRoutes');`,
    `const generalSettingRoutes = require('../routes/generalSettingRoutes');\nconst systemMaintenanceRoutes = require('../routes/systemMaintenanceRoutes');`,
    'Server system maintenance route import'
  );

  next = replaceOnce(
    next,
    `app.use('/api/general-settings', generalSettingRoutes);`,
    `app.use('/api/general-settings', generalSettingRoutes);\napp.use('/api/system-maintenance', systemMaintenanceRoutes);`,
    'Server system maintenance route mount'
  );

  next = replaceOnce(
    next,
    `    await ensureCanonicalIotOcrMigration();`,
    `    await ensureCanonicalIotOcrMigration();\n    await ensureSystemMaintenanceMigration();`,
    'Server system maintenance migration startup'
  );

  return next;
}

function patchMobileApp(source) {
  let next = normalize(source);
  if (next.includes('SMART-PDM_MOBILE_MAINTENANCE_GATE_V1')) return next;

  next = replaceOnce(
    next,
    `import 'package:smartpdm_mobileapp/app/theme/theme_provider.dart';`,
    `import 'package:smartpdm_mobileapp/app/theme/theme_provider.dart';\nimport 'package:smartpdm_mobileapp/core/maintenance/maintenance_mode_gate.dart'; // SMART-PDM_MOBILE_MAINTENANCE_GATE_V1`,
    'Mobile maintenance gate import'
  );

  next = replaceOnce(
    next,
    `              child: child ?? const SizedBox.shrink(),`,
    `              child: MaintenanceModeGate(\n                child: child ?? const SizedBox.shrink(),\n              ),`,
    'Mobile maintenance gate root wrapper'
  );

  return next;
}

function runCommand(command, args, options = {}) {
  const result = spawnSync(command, args, {
    cwd: options.cwd,
    encoding: 'utf8',
    windowsHide: true,
    stdio: options.inherit ? 'inherit' : 'pipe',
    shell: false,
  });

  if (result.error) return { ok: false, error: result.error, status: null, stdout: result.stdout || '', stderr: result.stderr || '' };
  return { ok: result.status === 0, status: result.status, stdout: result.stdout || '', stderr: result.stderr || '' };
}

function runNpmBuild(frontendDir) {
  console.log('\n> npm run build\n');
  let result;
  if (process.platform === 'win32') {
    const comspec = process.env.ComSpec || 'C:\\Windows\\System32\\cmd.exe';
    result = spawnSync(comspec, ['/d', '/s', '/c', 'npm run build'], {
      cwd: frontendDir,
      stdio: 'inherit',
      windowsHide: true,
    });
  } else {
    result = spawnSync('npm', ['run', 'build'], { cwd: frontendDir, stdio: 'inherit' });
  }
  if (result.error) throw result.error;
  if (result.status !== 0) fail(`Admin frontend build failed with exit code ${result.status}.`);
}

function checkNodeFile(filePath) {
  const result = runCommand(process.execPath, ['--check', filePath]);
  if (!result.ok) {
    fail(`Node syntax check failed for ${filePath}:\n${result.stderr || result.stdout}`);
  }
}

function probeFlutter() {
  const probe = process.platform === 'win32'
    ? spawnSync(process.env.ComSpec || 'C:\\Windows\\System32\\cmd.exe', ['/d', '/s', '/c', 'where flutter'], { encoding: 'utf8', windowsHide: true })
    : spawnSync('sh', ['-lc', 'command -v flutter'], { encoding: 'utf8' });
  return probe.status === 0;
}

function collectFlutterAnalyze(repoRoot, label) {
  const mobileDir = path.join(repoRoot, 'mobile', 'frontend');
  console.log(`\n> flutter analyze --no-fatal-infos --machine (${label})\n`);

  const result = process.platform === 'win32'
    ? spawnSync(
        process.env.ComSpec || 'C:\\Windows\\System32\\cmd.exe',
        ['/d', '/s', '/c', 'flutter analyze --no-fatal-infos --machine'],
        { cwd: mobileDir, encoding: 'utf8', windowsHide: true, maxBuffer: 32 * 1024 * 1024 }
      )
    : spawnSync(
        'flutter',
        ['analyze', '--no-fatal-infos', '--machine'],
        { cwd: mobileDir, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }
      );

  if (result.error) throw result.error;

  const stdout = result.stdout || '';
  const stderr = result.stderr || '';
  const combined = `${stdout}\n${stderr}`;
  const issueLines = combined
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => /^(INFO|WARNING|ERROR)\|/.test(line));

  const issueSet = new Set(issueLines);
  const severity = { INFO: 0, WARNING: 0, ERROR: 0 };
  for (const line of issueSet) {
    const key = line.split('|', 1)[0];
    if (Object.prototype.hasOwnProperty.call(severity, key)) severity[key] += 1;
  }

  const summaryMatch = combined.match(/(\d+)\s+issues?\s+found/i);
  const reportedCount = summaryMatch ? Number(summaryMatch[1]) : issueSet.size;

  console.log(
    `      Flutter baseline/result: ${reportedCount} issue(s) ` +
    `(${severity.ERROR} error, ${severity.WARNING} warning, ${severity.INFO} info)`
  );

  return {
    status: result.status,
    issues: issueSet,
    reportedCount,
    severity,
    stdout,
    stderr,
  };
}

function compareFlutterAnalyze(before, after) {
  const newIssues = [...after.issues].filter((issue) => !before.issues.has(issue));

  if (newIssues.length > 0) {
    const preview = newIssues.slice(0, 12).map((issue) => `        - ${issue}`).join('\n');
    const suffix = newIssues.length > 12 ? `\n        - ... ${newIssues.length - 12} more` : '';
    fail(
      `Flutter analyze introduced ${newIssues.length} new issue(s):\n${preview}${suffix}`
    );
  }

  // Machine output is the authoritative comparison. If Flutter returned a
  // non-zero status but emitted no machine-readable issues at all, treat it as
  // an analyzer/tool failure rather than silently accepting it.
  if (after.status !== 0 && after.issues.size === 0) {
    fail(`Flutter analyze failed with exit code ${after.status} and no analyzable diagnostics.`);
  }

  if (before.status !== 0 || before.issues.size > 0) {
    console.log('\nWARNING: Flutter analyze already had diagnostics before this patch.');
    console.log('No new Flutter analyzer issues were introduced, so the patch is being kept.');
  } else {
    console.log('\nPASS: Flutter analyze introduced no new issues.');
  }
}

function validateStaged(staged) {
  const maintenance = normalize(staged.get('admin/frontend/src/pages/maintenance/Maintenance.jsx').next);
  const general = normalize(staged.get('admin/frontend/src/pages/maintenance/GeneralPanel.jsx').next);
  const server = normalize(staged.get('admin/backend/server/server.js').next);
  const app = normalize(staged.get('mobile/frontend/lib/app/app.dart').next);
  const systemPanel = normalize(staged.get('admin/frontend/src/pages/maintenance/SystemPanel.jsx').next);

  const checks = [
    [maintenance.includes('data-maintenance-viewport-fit="true"'), 'Maintenance viewport-fit root'],
    [maintenance.includes('min-h-0 min-w-0 flex-1 overflow-auto'), 'Maintenance content scroll contract'],
    [!maintenance.includes('max-h-[calc(100vh-132px)]'), 'Old fixed Maintenance max-height removed'],
    [general.includes('<SystemPanel embedded editing={generalEditing} />'), 'General System panel edit-mode prop'],
    [server.includes("app.use('/api/system-maintenance', systemMaintenanceRoutes);"), 'System maintenance API mount'],
    [server.includes('await ensureSystemMaintenanceMigration();'), 'System maintenance startup migration'],
    [app.includes('MaintenanceModeGate('), 'Mobile maintenance gate'],
    [systemPanel.includes("/api/system-maintenance/backup"), 'Database backup button endpoint'],
    [systemPanel.includes('Tesseract + OpenCV'), 'Current OCR stack display'],
    [systemPanel.includes('Supabase object storage'), 'Live storage display'],
  ];

  for (const [passed, label] of checks) {
    if (!passed) fail(`Staged validation failed: ${label}`);
  }
}

function main() {
  const repoRoot = findRepoRoot(explicitRoot);
  const frontendDir = path.join(repoRoot, 'admin', 'frontend');
  const staged = new Map();

  console.log(PATCH_NAME);
  console.log(`Repository: ${repoRoot}`);
  console.log(`Mode: ${dryRun ? 'dry-run' : 'apply'}\n`);

  const readExisting = (relative) => {
    const absolute = path.join(repoRoot, relative);
    const original = fs.readFileSync(absolute, 'utf8');
    return { absolute, original, eol: detectEol(original) };
  };

  console.log('[1/5] Building live Maintenance Mode + student mobile gate...');
  {
    const server = readExisting('admin/backend/server/server.js');
    const app = readExisting('mobile/frontend/lib/app/app.dart');
    staged.set('admin/backend/server/server.js', {
      original: server.original,
      next: restoreEol(patchServer(server.original), server.eol),
      existed: true,
      changed: true,
    });
    staged.set('mobile/frontend/lib/app/app.dart', {
      original: app.original,
      next: restoreEol(patchMobileApp(app.original), app.eol),
      existed: true,
      changed: true,
    });
    upsertGeneratedFile(staged, repoRoot, 'admin/backend/services/systemMaintenanceMigrationService.js', decodePayload('admin/backend/services/systemMaintenanceMigrationService.js'));
    upsertGeneratedFile(staged, repoRoot, 'admin/backend/services/systemMaintenanceService.js', decodePayload('admin/backend/services/systemMaintenanceService.js'));
    upsertGeneratedFile(staged, repoRoot, 'admin/backend/controllers/systemMaintenanceController.js', decodePayload('admin/backend/controllers/systemMaintenanceController.js'));
    upsertGeneratedFile(staged, repoRoot, 'admin/backend/routes/systemMaintenanceRoutes.js', decodePayload('admin/backend/routes/systemMaintenanceRoutes.js'));
    upsertGeneratedFile(staged, repoRoot, 'supabase/migrations/20260825000100_system_maintenance_controls.sql', decodePayload('supabase/migrations/20260825000100_system_maintenance_controls.sql'));
    upsertGeneratedFile(staged, repoRoot, 'mobile/frontend/lib/core/maintenance/maintenance_mode_gate.dart', decodePayload('mobile/frontend/lib/core/maintenance/maintenance_mode_gate.dart'));
  }
  console.log('      PASS');

  console.log('[2/5] Building live System status + PostgreSQL SQL backup...');
  upsertGeneratedFile(staged, repoRoot, 'admin/frontend/src/pages/maintenance/SystemPanel.jsx', decodePayload('admin/frontend/src/pages/maintenance/SystemPanel.jsx'));
  console.log('      PASS');

  console.log('[3/5] Separating System actions from Edit mode while preserving setting protection...');
  {
    const file = readExisting('admin/frontend/src/pages/maintenance/GeneralPanel.jsx');
    staged.set('admin/frontend/src/pages/maintenance/GeneralPanel.jsx', {
      original: file.original,
      next: restoreEol(patchGeneralPanel(file.original), file.eol),
      existed: true,
      changed: true,
    });
  }
  console.log('      PASS');

  console.log('[4/5] Making Maintenance fit the available viewport at larger font sizes...');
  {
    const file = readExisting('admin/frontend/src/pages/maintenance/Maintenance.jsx');
    staged.set('admin/frontend/src/pages/maintenance/Maintenance.jsx', {
      original: file.original,
      next: restoreEol(patchMaintenance(file.original), file.eol),
      existed: true,
      changed: true,
    });
  }
  console.log('      PASS');

  console.log('[5/5] Validating staged integration...');
  validateStaged(staged);
  console.log('      PASS');

  if (dryRun) {
    console.log('\nPASS: dry-run completed. No files were changed.');
    return;
  }

  let flutterAvailable = false;
  let flutterBaseline = null;
  if (probeFlutter()) {
    console.log('\n[pre-write] Recording the existing Flutter analyzer baseline...');
    flutterAvailable = true;
    flutterBaseline = collectFlutterAnalyze(repoRoot, 'pre-write baseline');
    if (flutterBaseline.status !== 0 || flutterBaseline.issues.size > 0) {
      console.log(
        `      Existing Flutter analyzer: already has ${flutterBaseline.reportedCount} issue(s); ` +
        'v2 will allow only the same baseline and reject any new diagnostics.'
      );
    } else {
      console.log('      Existing Flutter analyzer: clean.');
    }
  } else {
    console.log('\nWARNING: Flutter CLI was not found in PATH, so Flutter analyzer comparison will be skipped.');
  }

  const backupDir = path.join(
    repoRoot,
    '.smart-pdm-patch-backup',
    `system-maintenance-backup-responsive-v2-${Date.now()}`
  );
  const written = [];

  try {
    for (const [relative, entry] of staged.entries()) {
      if (!entry.changed) continue;
      const absolute = path.join(repoRoot, relative);
      if (entry.existed) {
        const backupPath = path.join(backupDir, relative);
        fs.mkdirSync(path.dirname(backupPath), { recursive: true });
        fs.writeFileSync(backupPath, entry.original, 'utf8');
      }
      fs.mkdirSync(path.dirname(absolute), { recursive: true });
      fs.writeFileSync(absolute, entry.next, 'utf8');
      written.push({ relative, absolute, entry });
    }

    const jsChecks = [
      'admin/backend/services/systemMaintenanceMigrationService.js',
      'admin/backend/services/systemMaintenanceService.js',
      'admin/backend/controllers/systemMaintenanceController.js',
      'admin/backend/routes/systemMaintenanceRoutes.js',
      'admin/backend/server/server.js',
    ];
    for (const relative of jsChecks) {
      checkNodeFile(path.join(repoRoot, relative));
    }

    runNpmBuild(frontendDir);
    if (flutterAvailable) {
      const flutterAfter = collectFlutterAnalyze(repoRoot, 'after patch');
      compareFlutterAnalyze(flutterBaseline, flutterAfter);
    }

    console.log('\nPASS: Maintenance Mode + mobile lock screen + live System status + PostgreSQL SQL backup + viewport-fit Maintenance UI passed. Flutter analyzer was checked against its pre-existing baseline with no new issues.');
    console.log(`Backup: ${backupDir}`);
    console.log('\nNext: restart the backend once so the maintenance-mode database migration is applied, then rebuild/restart the mobile app.');
  } catch (error) {
    console.error('\nPatch verification failed. Restoring previous files...');
    for (const { absolute, entry } of written.reverse()) {
      try {
        if (entry.existed) fs.writeFileSync(absolute, entry.original, 'utf8');
        else if (fs.existsSync(absolute)) fs.unlinkSync(absolute);
      } catch (restoreError) {
        console.error(`Restore failed for ${absolute}: ${restoreError.message}`);
      }
    }
    console.error(`Rollback completed. Backup: ${backupDir}`);
    throw error;
  }
}

try {
  main();
} catch (error) {
  console.error(`\nFAIL: ${error.message || error}`);
  process.exitCode = 1;
}
